"""Generate manual-only diagnostic proposal. Never publishes or dispatches."""
import argparse,hashlib,json,pathlib,re
FILES=['profile.json','common.py','driver.py','native_entry.py','capture.py','collect.py','crypto_bridge.py','envelope.mjs','git_ack.py','transport_base.py','meter.py','meter_runner.py','observer.py','input_prep.py','make_workflow.py','run_checks.py','test_core.py','test_observer.py','test_integration.py','test_crypto.mjs','test_compilers.py','test_deadlines.py','test_volume_options.py','test_api_state.py','test_native_identity.py','test_artifact_consistency.py','test_receiver_metadata.py','test_mode_policy.py','live_resource.py','cleanup_owned.py','test_live_resource.py','test_cleanup_owned.py']
CHECKOUT='3d3c42e5aac5ba805825da76410c181273ba90b1'
UPLOAD='cf430e030ddbb5b0abf93d22962f4752f3646cd9'
def generate(folder,destination):
 rows=[]
 for name in FILES:
  raw=(folder/name).read_bytes();rows.append({'path':name,'bytes':len(raw),'sha256':hashlib.sha256(raw).hexdigest()})
 raw=(json.dumps({'schemaVersion':1,'firstPartyCodeOnly':True,'nativeActionsRequireConcreteOperatorReview':True,'files':rows},sort_keys=True,indent=2)+'\n').encode();manifest=folder/'MANIFEST.json';manifest.write_bytes(raw);pin=hashlib.sha256(raw).hexdigest();p='scripts/producer-sdk10/driver.py';cmd='python3 -I -S -B '+p
 lines=['# DIAGNOSTIC PROPOSAL ONLY. Do not replace ordinary main CI with this file.','name: SDK10 original producer diagnostic','on:','  workflow_dispatch:','    inputs:','      nonce:','        description: Exact reviewed fresh lowercase nonce','        required: true','        type: string','      operator_ack:','        description: sdk10-original-e34-240m-'+pin[:12],'        required: true','        type: string','      recipient_jwk:','        description: RSA3072..4096 public-only JWK; private key remains local','        required: true','        type: string','      ack_parent:','        description: Exact preexisting dedicated diagnostic recovery-ref commit','        required: true','        type: string','permissions:','  contents: read','  actions: read','concurrency:','  group: checktrail-sdk10-original-manual','  cancel-in-progress: false','jobs:','  sdk10-original:','    name: sdk10-original','    runs-on: ubuntu-26.04','    timeout-minutes: 360','    env:','      CHECKTRAIL_NONCE: ${{ inputs.nonce }}','      CHECKTRAIL_OPERATOR_ACK: ${{ inputs.operator_ack }}','      CHECKTRAIL_RECIPIENT_JWK: ${{ inputs.recipient_jwk }}','      CHECKTRAIL_ACK_PARENT: ${{ inputs.ack_parent }}','      CHECKTRAIL_MANIFEST_SHA256: '+pin,'      GH_TOKEN: ${{ github.token }}','    steps:','      - name: Read reviewed first-party diagnostic controller','        uses: actions/checkout@'+CHECKOUT+' # v7.0.1','        with:','          persist-credentials: false','          fetch-depth: 1','      - name: Verify all first-party synthetic controls','        timeout-minutes: 7','        shell: bash','        run: python3 -I -S -B scripts/producer-sdk10/run_checks.py --out "$RUNNER_TEMP/sdk10-synthetic-controls" --manifest-sha256 "$CHECKTRAIL_MANIFEST_SHA256"','      - name: Original SDK10 producer and private stopped-evidence encryption','        id: producer','        continue-on-error: true','        shell: bash','        run: '+cmd+' produce --nonce "$CHECKTRAIL_NONCE" --manifest-sha256 "$CHECKTRAIL_MANIFEST_SHA256"']
 for w in range(1,50):
  prev=" && steps.wait_"+str(w-1).zfill(2)+".outcome == 'success'" if w>1 else '';ready="always() && steps.producer.outputs.capture_ready == 'true' && fromJSON(steps.producer.outputs.total_carriers || '0') >= "+str(w*2)+prev;ws=str(w).zfill(2);prepare='prepare_'+ws;up=['upload_'+ws+'_a','upload_'+ws+'_b'];record='record_'+ws;wait='wait_'+ws
  lines+=['      - name: Prepare exact two-slot SDK10 window '+ws,'        id: '+prepare,'        if: '+ready,'        shell: bash','        run: '+cmd+' prepare-window --window '+str(w)+' --nonce "$CHECKTRAIL_NONCE" --manifest-sha256 "$CHECKTRAIL_MANIFEST_SHA256"']
  for ix,ordinal in enumerate([w*2-1,w*2]):
   lines+=['      - name: Upload encrypted SDK10 carrier '+str(ordinal).zfill(6),'        id: '+up[ix],'        if: always() && steps.'+prepare+".outcome == 'success'",'        uses: actions/upload-artifact@'+UPLOAD+' # v7.0.2','        with:','          name: ct-sdk10-native-${{ github.run_id }}-1-${{ inputs.nonce }}-'+str(ordinal).zfill(6),'          path: ${{ runner.temp }}/ct-sdk10-${{ inputs.nonce }}/windows/'+ws+'/'+str(ordinal).zfill(6)+'/*','          if-no-files-found: error','          compression-level: 0','          retention-days: 1','          overwrite: false']
  lines+=['      - name: Record exact SDK10 two-slot window '+ws,'        id: '+record,"        if: always() && steps."+up[0]+".outcome == 'success' && steps."+up[1]+".outcome == 'success'",'        shell: bash','        env:','          EXACT_ARTIFACT_IDS: ${{ steps.'+up[0]+'.outputs.artifact-id }},${{ steps.'+up[1]+'.outputs.artifact-id }}','        run: '+cmd+' record-window --window '+str(w)+' --ids "$EXACT_ARTIFACT_IDS" --nonce "$CHECKTRAIL_NONCE" --manifest-sha256 "$CHECKTRAIL_MANIFEST_SHA256"','      - name: Wait for exact owned SDK10 window '+ws+' recovery','        id: '+wait,"        if: always() && steps."+record+".outcome == 'success'",'        shell: bash','        run: '+cmd+' wait-window --window '+str(w)+' --nonce "$CHECKTRAIL_NONCE" --manifest-sha256 "$CHECKTRAIL_MANIFEST_SHA256"']
 lines+=['      - name: Verify signed recovery and clean only owned resources','        if: always()','        shell: bash','        run: '+cmd+' finalize --nonce "$CHECKTRAIL_NONCE" --manifest-sha256 "$CHECKTRAIL_MANIFEST_SHA256"'];body=('\n'.join(lines)+'\n').encode();destination.write_bytes(body);return {'workflow':str(destination),'workflowBytes':len(body),'workflowSHA256':hashlib.sha256(body).hexdigest(),'manifestSHA256':pin,'maximumWindows':49,'maximumCarrierSlots':2,'jobs':1,'workflowManualOnly':True,'nativeCommandSecondsUnchanged':14400,'wholeControllerSeconds':21000,'hostedJobSeconds':21600}
if __name__=='__main__':
 p=argparse.ArgumentParser();p.add_argument('--folder',type=pathlib.Path,required=True);p.add_argument('--out',type=pathlib.Path,required=True);a=p.parse_args();print(json.dumps(generate(a.folder,a.out),sort_keys=True))
